import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0
    times = sorted({t for start, end, _pay in jobs for t in (start, end)})
    pos = {t: i for i, t in enumerate(times)}
    n = len(times)
    graph: list[list[list[int]]] = [[] for _ in range(n)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        graph[u].append([v, cap, cost, len(graph[v])])
        graph[v].append([u, 0, -cost, len(graph[u]) - 1])

    for i in range(n - 1):
        add_edge(i, i + 1, k, 0)
    for start, end, pay in jobs:
        add_edge(pos[start], pos[end], 1, -pay)

    inf = 10**18
    potential = [inf] * n
    potential[0] = 0
    for u in range(n):
        if potential[u] >= inf:
            continue
        for v, cap, cost, _rev in graph[u]:
            if cap > 0 and potential[v] > potential[u] + cost:
                potential[v] = potential[u] + cost

    sink = n - 1
    total = 0
    sent = 0
    while sent < k:
        dist = [inf] * n
        dist[0] = 0
        parent = [(-1, -1)] * n
        heap = [(0, 0)]
        while heap:
            d, u = heapq.heappop(heap)
            if d != dist[u]:
                continue
            for ei, (v, cap, cost, _rev) in enumerate(graph[u]):
                if cap <= 0:
                    continue
                nd = d + cost + potential[u] - potential[v]
                if nd < dist[v]:
                    dist[v] = nd
                    parent[v] = (u, ei)
                    heapq.heappush(heap, (nd, v))
        if dist[sink] >= inf:
            break
        path_cost = dist[sink] + potential[sink] - potential[0]
        if path_cost >= 0:
            break
        for i in range(n):
            if dist[i] < inf:
                potential[i] += dist[i]
        delta = k - sent
        v = sink
        while v != 0:
            u, ei = parent[v]
            delta = min(delta, graph[u][ei][1])
            v = u
        v = sink
        while v != 0:
            u, ei = parent[v]
            graph[u][ei][1] -= delta
            rev = graph[u][ei][3]
            graph[v][rev][1] += delta
            v = u
        sent += delta
        total += delta * path_cost
    return -total
